SELECT 
FROM runtime_rewrite_binding
WHERE tenant_id = #{tenantId}
  AND sql_fingerprint = #{sqlFingerprint}
  AND status = 'ACTIVE'
LIMIT 1

SELECT 
FROM runtime_rewrite_binding
WHERE tenant_id = #{tenantId}
  AND sql_fingerprint = #{sqlFingerprint}
ORDER BY rule_version DESC, created_at DESC
LIMIT 1

SELECT 
FROM runtime_rewrite_binding
WHERE tenant_id = #{tenantId}
  AND sql_fingerprint = #{sqlFingerprint}
ORDER BY rule_version DESC, created_at DESC
